 const profile=u?.employeeId&&typeof state!=='undefined'?(state.staffProfiles||[]).find(p=>String(p.id)===String(u.employeeId)):null;
 const managed=!!profile&&typeof isStaffAssignable==='function'&&isStaffAssignable(profile)&&Object.entries(state.departmentManagers||{}).some(([d,id])=>String(id)===String(u.employeeId)&&deptApp(d)===app);
 if((r?.scope==='department'||r?.scope==='department_limited')&&(app===da||managed))base=!!r?.scopeActions?.[action];
