function semanticAction(el){const t=clean(el.innerText||el.textContent||el.getAttribute?.('title')||'');if(!t)return '';
 if(/حذف|مسح|إلغاء الأمر|إلغاء العرض|إلغاء الطلب/.test(t))return 'delete';
 if(/اعتماد|موافقة|رفض/.test(t))return 'approve';
 if(/توزيع|إسناد|تعيين موظف|تحديد المسؤول/.test(t))return 'assign';
 if(/تغيير الحالة|بدء العمل|إنهاء العمل|استلام المهمة|إرسال للمراجعة|إعادة للتعديل|قيد التنفيذ/.test(t))return 'status';
 if(/مرفق|المرفقات|رفع ملف|رفع صورة|رفع فيديو/.test(t))return 'attachments';
 if(/تقرير|تقارير|كشف حساب|ميزان|قائمة دخل/.test(t))return 'reports';
 if(/طباعة|pdf/i.test(t))return 'print';
 if(/تصدير|excel|csv/i.test(t))return 'export';
 if(/^\s*\+|إنشاء|إضافة|جديد|استلام جديد|صرف جديد|إدخال/.test(t))return 'create';
 if(/تعديل|تحرير|حفظ/.test(t))return 'edit';
 if(/فتح|تفاصيل|عرض التفاصيل/.test(t))return 'details';
 if(/قائمة|سجل|الأرشيف|العملاء|الموردين|الأصناف|الفواتير/.test(t))return 'list'; return '';
}
function specialAction(el){const t=clean(el.innerText||el.textContent||'');if(/لوحة التحكم|القائمة الرئيسية/.test(t))return 'dashboard';if(t==='مهام جارية'||t==='المهام الجارية'||t==='مهامي'||t==='مهام الإدارة'||t.startsWith('مهام قسم '))return 'running';if(t.includes('اعتماد المدير'))return 'approvals';return ''}
function applyElement(el,hide){if(!el)return;if(hide){if(!el.hasAttribute('data-auth37-display')){el.setAttribute('data-auth37-display',el.style.getPropertyValue('display')||'');el.setAttribute('data-auth37-display-priority',el.style.getPropertyPriority('display')||'')}el.classList.add('mosh-auth-hidden');el.style.setProperty('display','none','important')}else{el.classList.remove('mosh-auth-hidden');if(el.hasAttribute('data-auth37-display')){const v=el.getAttribute('data-auth37-display')||'',p=el.getAttribute('data-auth37-display-priority')||'';if(v)el.style.setProperty('display',v,p);else el.style.removeProperty('display');el.removeAttribute('data-auth37-display');el.removeAttribute('data-auth37-display-priority')}}}
